using System.Drawing.Printing;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.App.Forms;

public sealed class SalesForm : PharmacyForm
{
    private readonly StockManagementService stock=new(new DatabaseInitializer());
    private readonly SalesAndCashService sales=new(new DatabaseInitializer());
    private readonly long userId;
    private long? cashSessionId;
    private bool checkoutPending;
    private string? pendingCheckoutKey;
    private readonly TextBox query=new(){Dock=DockStyle.Top,PlaceholderText="Scanner un code-barres ou rechercher un produit"};
    private readonly DataGridView products=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false};
    private readonly DataGridView basket=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false};
    private readonly BindingSource cartSource=new();
    private readonly List<CartLine> cart=[];
    private readonly Label total=new(){Text="Total : 0",AutoSize=true,Font=new Font("Segoe UI",18,FontStyle.Bold)};
    public SalesForm(long authenticatedUserId){userId=authenticatedUserId;Text="Vente au comptoir";MinimumSize=new Size(1000,650);WindowState=FormWindowState.Maximized;KeyPreview=true;var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=540};var left=new Panel{Dock=DockStyle.Fill};left.Controls.Add(products);left.Controls.Add(query);split.Panel1.Controls.Add(left);basket.DataSource=cartSource;split.Panel2.Controls.Add(basket);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=76,Padding=new Padding(8),FlowDirection=FlowDirection.LeftToRight};var add=new Button{Text="Ajouter au panier",AutoSize=true};var qty=new NumericUpDown{Minimum=1,Maximum=9999,Value=1,Width=70};var remove=new Button{Text="Retirer la ligne",AutoSize=true};var open=new Button{Text="Ouvrir caisse",AutoSize=true};var close=new Button{Text="Clôturer caisse",AutoSize=true};var reprintId=new NumericUpDown{Minimum=1,Maximum=long.MaxValue,Width=90};var reprint=new Button{Text="Réimprimer ticket n°",AutoSize=true};var collect=new Button{Text="Encaisser",AutoSize=true,BackColor=Color.FromArgb(22,112,96),ForeColor=Color.White,Font=new Font("Segoe UI",12,FontStyle.Bold)};collect.Click+=async(_,_)=>await Checkout();add.Click+=(_,_)=>AddProduct((int)qty.Value);remove.Click+=(_,_)=>{if(basket.CurrentRow?.DataBoundItem is CartLine line){cart.Remove(line);RefreshCart();}};open.Click+=async(_,_)=>await OpenCash();close.Click+=async(_,_)=>await CloseCash();reprint.Click+=async(_,_)=>{try{PrintTicket(await sales.GetReceiptAsync((long)reprintId.Value));}catch(Exception ex){MessageBox.Show(ex.Message,"Ticket introuvable",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};bottom.Controls.AddRange([add,qty,remove,open,close,reprintId,reprint,total,collect]);Controls.Add(split);Controls.Add(bottom);query.TextChanged+=async(_,_)=>await LoadProducts();query.KeyDown+=async(_,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;if(products.Rows.Count>0){products.CurrentCell=products.Rows[0].Cells[0];AddProduct(1);}query.SelectAll();}};products.CellDoubleClick+=(_,_)=>AddProduct((int)qty.Value);Shown+=async(_,_)=>{cashSessionId=await sales.GetOpenCashSessionAsync();await LoadProducts();};KeyDown+=(_,e)=>{if(e.KeyCode==Keys.F2){query.Focus();query.SelectAll();}if(e.KeyCode==Keys.Delete&&basket.Focused&&basket.CurrentRow?.DataBoundItem is CartLine line){cart.Remove(line);RefreshCart();}};}
    private async Task LoadProducts(){try{products.DataSource=await stock.GetProductsAsync(query.Text.Length==0?null:query.Text,active:true,available:true);if(products.Columns.Contains("ProductId"))products.Columns["ProductId"]!.Visible=false;}catch(Exception ex){MessageBox.Show(ex.Message,"Recherche impossible",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    private void AddProduct(int quantity){if(products.CurrentRow?.DataBoundItem is not ProductStock p)return;var old=cart.FindIndex(x=>x.ProductId==p.ProductId);var next=(old<0?0:cart[old].Quantity)+quantity;if(next>p.Sellable){MessageBox.Show("Quantité supérieure au stock vendable.","Stock insuffisant",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(old>=0)cart[old]=cart[old] with{Quantity=next};else cart.Add(new CartLine(p.ProductId,p.Code,p.Name,p.SalePriceMinor,quantity));RefreshCart();}
    private long ReadPrice(long id){var row=products.Rows.Cast<DataGridViewRow>().First(x=>x.DataBoundItem is ProductStock p&&p.ProductId==id);return Convert.ToInt64(row.Cells.Cast<DataGridViewCell>().First(x=>x.OwningColumn.Name=="SalePriceMinor").Value);}
    private void RefreshCart(){cartSource.DataSource=null;cartSource.DataSource=cart.Select(x=>new{ x.ProductId,x.Code,x.Name,x.Quantity,UnitPrice=x.UnitPriceMinor,Subtotal=x.UnitPriceMinor*x.Quantity}).ToList();total.Text=$"Total : {cart.Sum(x=>x.UnitPriceMinor*x.Quantity)/100m:N2}";}
    private async Task OpenCash(){using var f=new PharmacyForm{Text="Ouverture de caisse",Width=350,Height=180,StartPosition=FormStartPosition.CenterParent};var amount=new NumericUpDown{Left=20,Top=25,Width=280,Maximum=100000000,DecimalPlaces=2,ThousandsSeparator=true};var ok=new Button{Text="Ouvrir",Left=220,Top=75,DialogResult=DialogResult.OK};f.Controls.AddRange([new Label{Text="Fonds initial",Left=20,Top=5},amount,ok]);if(f.ShowDialog(this)!=DialogResult.OK)return;try{cashSessionId=await sales.OpenCashSessionAsync(userId,decimal.ToInt64(amount.Value*100));MessageBox.Show("Caisse ouverte.","Caisse",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Ouverture impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private async Task CloseCash(){if(cashSessionId is null){MessageBox.Show("Aucune session de caisse n'est ouverte dans cet écran.");return;}using var f=new PharmacyForm{Text="Clôture de caisse",Width=380,Height=180,StartPosition=FormStartPosition.CenterParent};var count=new NumericUpDown{Left=20,Top=35,Width=300,Maximum=100000000,DecimalPlaces=2,ThousandsSeparator=true};var ok=new Button{Text="Clôturer",Left=220,Top=80,DialogResult=DialogResult.OK};f.Controls.AddRange([new Label{Text="Espèces comptées",Left=20,Top=10},count,ok]);if(f.ShowDialog(this)!=DialogResult.OK)return;try{await sales.CloseCashSessionAsync(cashSessionId.Value,userId,decimal.ToInt64(count.Value*100));cashSessionId=null;MessageBox.Show("Clôture enregistrée.","Caisse",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Clôture impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private async Task Checkout(){if(checkoutPending||cart.Count==0)return;if(cashSessionId is null){MessageBox.Show("Ouvrez une caisse avant d'encaisser.");return;}var amount=cart.Sum(x=>x.UnitPriceMinor*x.Quantity);using var f=new PharmacyForm{Text="Encaissement",Width=430,Height=290,StartPosition=FormStartPosition.CenterParent};var method=new ComboBox{Left=25,Top=35,Width=350,DropDownStyle=ComboBoxStyle.DropDownList};method.Items.AddRange(["ESPECES","CARTE","MOBILE"]);method.SelectedIndex=0;var received=new NumericUpDown{Left=25,Top=100,Width=350,Maximum=100000000,DecimalPlaces=2,Value=amount/100m};var confirm=new TextBox{Left=25,Top=160,Width=350,PlaceholderText="Confirmation manuelle carte/mobile"};var ok=new Button{Text="Valider le paiement",Left=245,Top=205,Width=130,DialogResult=DialogResult.OK};f.Controls.AddRange([new Label{Text=$"À payer : {amount/100m:N2}",Left=25,Top=10},method,new Label{Text="Montant reçu",Left=25,Top=78},received,confirm,ok]);method.SelectedIndexChanged+=(_,_)=>{received.Enabled=method.SelectedItem?.ToString()=="ESPECES";};if(f.ShowDialog(this)!=DialogResult.OK)return;checkoutPending=true;try{pendingCheckoutKey??=Guid.NewGuid().ToString("N");var kind=method.SelectedItem!.ToString()!;var paid=kind=="ESPECES"?decimal.ToInt64(received.Value*100):amount;if(kind=="ESPECES"&&paid<amount)throw new InvalidOperationException("Montant reçu insuffisant.");var id=await sales.CheckoutAsync(new(userId,cashSessionId,cart.ToArray(),[new(kind,amount,kind=="ESPECES"?null:confirm.Text)],0,pendingCheckoutKey));pendingCheckoutKey=null;cart.Clear();RefreshCart();var ticket=await sales.GetReceiptAsync(id);PrintTicket(ticket);MessageBox.Show(kind=="ESPECES"?$"Vente enregistrée. Monnaie à rendre : {(paid-amount)/100m:N2}":"Vente enregistrée.","Encaissement confirmé",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Vente non enregistrée",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{checkoutPending=false;}}
    private void PrintTicket(SaleReceipt ticket){var text=$"{ticket.PharmacyName}\n{ticket.PharmacyAddress}\n{ticket.PharmacyPhone}\nTicket {ticket.Number}\n{ticket.Date:dd/MM/yyyy HH:mm}\nVendeur : {ticket.Seller}\n------------------------------\n"+string.Join("\n",ticket.Lines.Select(l=>$"{l.Name} x{l.Quantity}  {l.UnitPriceMinor/100m:N2}"))+$"\nRemise : {ticket.DiscountMinor/100m:N2}\nTOTAL : {ticket.TotalMinor/100m:N2}\nPaiement : {string.Join(", ",ticket.Payments.Select(p=>$"{p.Method} {p.AmountMinor/100m:N2}"))}";var doc=new PrintDocument();doc.PrintPage+=(_,e)=>{e.Graphics!.DrawString(text,new Font("Consolas",10),Brushes.Black,new RectangleF(10,10,e.MarginBounds.Width,e.MarginBounds.Height));};try{doc.Print();}catch(Exception ex){MessageBox.Show($"Vente enregistrée. Impression indisponible : {ex.Message}\n{text}","Ticket",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
}
